import React, { useEffect, useMemo, useRef, useState, useCallback } from "react";
import "../styles/OpenClawMissionControl.css";
import { supabase, isConfigured as isSupabaseConfigured } from "../lib/supabase";

const statusPriority = {
  active: 0,
  standby: 1,
  idle: 2,
};

const statusLabel = {
  active: "ACTIVE",
  standby: "STANDBY",
  idle: "IDLE",
};

const sourceLabel = {
  discord: "Discord",
  webchat: "Webchat",
  telegram: "Telegram",
};

const zoneLabel = {
  breakroom: "Breakroom",
  desk: "Desk Zone",
  issue: "Problem Solving",
};

const zoneDescription = {
  breakroom: "Idle assistants rest and wait for new tasks.",
  desk: "Active assistants are currently executing work.",
  issue: "Standby assistants review blockers or debug issues.",
};

const bubbleByStatus = {
  active: "Working...",
  standby: "Checking issue",
  idle: "On break",
};

const zoneSlots = {
  breakroom: [
    { x: 48, y: 50 },
    { x: 53, y: 52 },
    { x: 57, y: 49 },
    { x: 50, y: 57 },
  ],
  desk: [
    { x: 24, y: 50 },
    { x: 28, y: 54 },
    { x: 20, y: 56 },
    { x: 30, y: 52 },
  ],
  issue: [
    { x: 89, y: 37 },
    { x: 85, y: 40 },
    { x: 92, y: 41 },
    { x: 88, y: 44 },
  ],
};

const zoneTransitWaypoint = {
  breakroom: { x: 43, y: 50 },
  desk: { x: 34, y: 53 },
  issue: { x: 82, y: 38 },
};

const centralTransitPoint = { x: 56, y: 46 };

const agentSpriteFiles = [
  { file: "agent-1.webp", hueRotate: 0 },
  { file: "agent-2.webp", hueRotate: 0 },
  { file: "agent-3.webp", hueRotate: 0 },
  { file: "agent-4.webp", hueRotate: 0 },
  { file: "agent-5.webp", hueRotate: 0 },
  { file: "agent-6.webp", hueRotate: 0 },
  { file: "agent-7.webp", hueRotate: 0 },
];

const fallbackFeed = {
  generatedAt: null,
  summary: {
    agentCount: 0,
    activeNow: 0,
    events24h: 0,
    events7d: 0,
  },
  agents: [],
  timeline: [],
};

const FALLBACK_POLL_INTERVAL_MS = 10000;
const OFFICE_MOVE_STEP_MS = 640;
const WANDER_INTERVAL_MS = 3000;
const WANDER_RANGE = 3.5;

const relativeFormatter =
  typeof Intl !== "undefined" && Intl.RelativeTimeFormat
    ? new Intl.RelativeTimeFormat("en", { numeric: "auto" })
    : null;

const numberFormatter = new Intl.NumberFormat("en-US");

const formatAbsoluteTime = (value) => {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";

  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
};

const formatRelativeTime = (value) => {
  if (!value) return "No signal";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "No signal";

  const diffMs = date.getTime() - Date.now();
  const absMs = Math.abs(diffMs);

  const units = [
    ["day", 24 * 60 * 60 * 1000],
    ["hour", 60 * 60 * 1000],
    ["minute", 60 * 1000],
  ];

  for (const [unit, unitMs] of units) {
    if (absMs >= unitMs || unit === "minute") {
      const delta = Math.round(diffMs / unitMs);
      if (relativeFormatter) {
        return relativeFormatter.format(delta, unit);
      }
      return `${Math.abs(delta)} ${unit}${Math.abs(delta) > 1 ? "s" : ""} ${
        delta < 0 ? "ago" : "from now"
      }`;
    }
  }

  return "just now";
};

const normalizeFeed = (data) => ({
  ...fallbackFeed,
  ...data,
  summary: {
    ...fallbackFeed.summary,
    ...(data?.summary || {}),
  },
  agents: Array.isArray(data?.agents) ? data.agents : [],
  timeline: Array.isArray(data?.timeline) ? data.timeline : [],
});

const getAvatarUrl = (fileName) => {
  if (!fileName) return "";
  return `${process.env.PUBLIC_URL}/openclaw/avatars/${fileName}`;
};

const getOfficeAssetUrl = (fileName) =>
  `${process.env.PUBLIC_URL}/openclaw/office/star-assets/${fileName}`;

const getZoneByStatus = (agent) => {
  if (agent.status === "active") return "desk";
  if (agent.status === "standby") return "issue";
  return "breakroom";
};

const distanceBetween = (a, b) => Math.hypot((a?.x || 0) - (b?.x || 0), (a?.y || 0) - (b?.y || 0));

const toSortedOfficeAgents = (stateMap) =>
  Array.from(stateMap.values()).sort((a, b) => {
    const statusA = statusPriority[a.status] ?? 99;
    const statusB = statusPriority[b.status] ?? 99;
    if (statusA !== statusB) return statusA - statusB;
    return String(a.id).localeCompare(String(b.id));
  });

const buildAgentTransitionPath = (currentAgent, targetAgent) => {
  const from = { x: currentAgent.x, y: currentAgent.y };
  const to = { x: targetAgent.x, y: targetAgent.y };

  if (distanceBetween(from, to) < 0.5) return [];

  if (currentAgent.zone === targetAgent.zone) {
    return [to];
  }

  const rawPath = [
    zoneTransitWaypoint[currentAgent.zone],
    centralTransitPoint,
    zoneTransitWaypoint[targetAgent.zone],
    to,
  ].filter(Boolean);

  const compacted = [];
  let cursor = from;
  for (const point of rawPath) {
    if (distanceBetween(cursor, point) >= 1.1) {
      compacted.push({ x: point.x, y: point.y });
      cursor = point;
    }
  }

  if (!compacted.length || distanceBetween(compacted[compacted.length - 1], to) >= 0.6) {
    compacted.push(to);
  }

  return compacted;
};

const OpenClawMissionControl = () => {
  const [feed, setFeed] = useState(fallbackFeed);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [connectionStatus, setConnectionStatus] = useState("connecting");
  const [officeRenderAgents, setOfficeRenderAgents] = useState([]);
  const firstLoadRef = useRef(true);
  const officeAgentStateRef = useRef(new Map());
  const moveTimersRef = useRef(new Map());

  const clearAgentTimers = (agentId) => {
    const timers = moveTimersRef.current.get(agentId);
    if (!timers) return;
    timers.forEach((timerId) => clearTimeout(timerId));
    moveTimersRef.current.delete(agentId);
  };

  const publishOfficeAgents = () => {
    setOfficeRenderAgents(toSortedOfficeAgents(officeAgentStateRef.current));
  };

  const handlePayload = useCallback((payload) => {
    const data = payload?.payload;
    if (data) {
      setFeed(normalizeFeed(data));
      setError("");
    }
    if (firstLoadRef.current) {
      setLoading(false);
      firstLoadRef.current = false;
    }
  }, []);

  useEffect(() => {
    if (!isSupabaseConfigured || !supabase) {
      // Fallback: static JSON polling when Supabase is not configured
      let cancelled = false;

      const loadFeed = async () => {
        try {
          const feedUrl = `${process.env.PUBLIC_URL}/openclaw/agent-feed.json?v=${Date.now()}`;
          const res = await fetch(feedUrl, { cache: "no-store" });
          if (!res.ok) {
            throw new Error(`Feed request failed (${res.status})`);
          }
          const data = await res.json();
          if (cancelled) return;
          setFeed(normalizeFeed(data));
          setError("");
          setConnectionStatus("fallback");
        } catch (err) {
          if (cancelled) return;
          setError(err?.message || "Failed to load OpenClaw feed");
        } finally {
          if (cancelled) return;
          if (firstLoadRef.current) {
            setLoading(false);
            firstLoadRef.current = false;
          }
        }
      };

      loadFeed();
      const intervalId = setInterval(loadFeed, FALLBACK_POLL_INTERVAL_MS);

      return () => {
        cancelled = true;
        clearInterval(intervalId);
      };
    }

    // Supabase mode
    let cancelled = false;
    let pollIntervalId = null;
    let realtimeActive = false;

    const fetchFromSupabase = async () => {
      try {
        const { data, error: fetchError } = await supabase
          .from("agent_snapshots")
          .select("payload")
          .eq("id", "latest")
          .single();

        if (cancelled) return;

        if (fetchError) {
          setError(`Supabase fetch failed: ${fetchError.message}`);
        } else if (data?.payload) {
          setFeed(normalizeFeed(data.payload));
          setError("");
        }
      } catch (err) {
        if (cancelled) return;
        setError(err?.message || "Failed to fetch from Supabase");
      } finally {
        if (cancelled) return;
        if (firstLoadRef.current) {
          setLoading(false);
          firstLoadRef.current = false;
        }
      }
    };

    // Start REST polling as baseline (works even if Realtime fails)
    const startPolling = () => {
      if (pollIntervalId) return;
      pollIntervalId = setInterval(fetchFromSupabase, FALLBACK_POLL_INTERVAL_MS);
    };

    const stopPolling = () => {
      if (pollIntervalId) {
        clearInterval(pollIntervalId);
        pollIntervalId = null;
      }
    };

    // Initial fetch
    fetchFromSupabase();

    // Try Realtime subscription
    const channel = supabase
      .channel("agent-snapshots-realtime")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "agent_snapshots",
          filter: "id=eq.latest",
        },
        (payload) => {
          if (cancelled) return;
          const row = payload.new;
          if (row?.payload) {
            setFeed(normalizeFeed(row.payload));
            setError("");
          }
        }
      )
      .subscribe((status) => {
        if (cancelled) return;
        if (status === "SUBSCRIBED") {
          realtimeActive = true;
          setConnectionStatus("connected");
          stopPolling();
        } else if (status === "CLOSED" || status === "CHANNEL_ERROR" || status === "TIMED_OUT") {
          realtimeActive = false;
          setConnectionStatus("polling");
          startPolling();
        }
      });

    // If Realtime doesn't connect within 5s, start polling
    const realtimeTimeout = setTimeout(() => {
      if (!realtimeActive && !cancelled) {
        setConnectionStatus("polling");
        startPolling();
      }
    }, 5000);

    return () => {
      cancelled = true;
      clearTimeout(realtimeTimeout);
      stopPolling();
      supabase.removeChannel(channel);
    };
  }, [handlePayload]);

  const agents = useMemo(() => {
    const source = Array.isArray(feed.agents) ? feed.agents : [];

    return [...source].sort((a, b) => {
      const statusA = statusPriority[a.status] ?? 99;
      const statusB = statusPriority[b.status] ?? 99;
      if (statusA !== statusB) return statusA - statusB;

      const signalA = Date.parse(a.lastSignalAt || "") || 0;
      const signalB = Date.parse(b.lastSignalAt || "") || 0;
      return signalB - signalA;
    });
  }, [feed.agents]);

  const agentDisplayNames = useMemo(() => {
    const ids = [...new Set(agents.map((agent) => agent.id).filter(Boolean))].sort((a, b) =>
      a.localeCompare(b)
    );

    return ids.reduce((acc, id, index) => {
      acc[id] = `Agent ${index + 1}`;
      return acc;
    }, {});
  }, [agents]);

  const agentSpriteById = useMemo(() => {
    const ids = [...new Set(agents.map((agent) => agent.id).filter(Boolean))].sort((a, b) =>
      a.localeCompare(b)
    );

    return ids.reduce((acc, id, index) => {
      const sprite = agentSpriteFiles[index % agentSpriteFiles.length];
      acc[id] = sprite;
      return acc;
    }, {});
  }, [agents]);

  const getDisplayName = (agentId, fallback) => {
    return agentDisplayNames[agentId] || fallback || agentId || "Agent";
  };

  const getSpriteInfo = (agentId) => {
    const sprite = agentSpriteById[agentId] || agentSpriteFiles[0];
    return {
      url: getAvatarUrl(sprite.file),
      hueRotate: sprite.hueRotate || 0,
    };
  };

  const getBubbleText = (agent) => {
    if (!agent.isMoving) return "";
    return bubbleByStatus[agent.status] || "Moving";
  };

  const officeTargets = useMemo(() => {
    const grouped = {
      breakroom: [],
      desk: [],
      issue: [],
    };

    for (const agent of agents) {
      grouped[getZoneByStatus(agent)].push(agent);
    }

    return Object.entries(grouped).flatMap(([zone, zoneAgents]) =>
      zoneAgents.map((agent, index) => {
        const slots = zoneSlots[zone] || [{ x: 50, y: 50 }];
        const base = slots[index % slots.length];
        const rowOffset = Math.floor(index / slots.length);

        return {
          ...agent,
          zone,
          x: base.x + rowOffset * 3.4,
          y: base.y + rowOffset * 2.4,
        };
      })
    );
  }, [agents]);

  useEffect(() => {
    const targetById = new Map(officeTargets.map((agent) => [agent.id, agent]));
    const currentMap = officeAgentStateRef.current;

    for (const currentId of [...currentMap.keys()]) {
      if (!targetById.has(currentId)) {
        clearAgentTimers(currentId);
        currentMap.delete(currentId);
      }
    }

    for (const target of officeTargets) {
      const current = currentMap.get(target.id);

      if (!current) {
        currentMap.set(target.id, {
          ...target,
          isMoving: false,
        });
        continue;
      }

      const hasPositionChanged =
        current.zone !== target.zone ||
        Math.abs((current.x || 0) - target.x) > 0.05 ||
        Math.abs((current.y || 0) - target.y) > 0.05;

      if (!hasPositionChanged) {
        currentMap.set(target.id, {
          ...current,
          ...target,
          isMoving: false,
        });
        continue;
      }

      clearAgentTimers(target.id);

      const path = buildAgentTransitionPath(current, target);

      if (!path.length) {
        currentMap.set(target.id, {
          ...current,
          ...target,
          isMoving: false,
        });
        continue;
      }

      currentMap.set(target.id, {
        ...current,
        ...target,
        isMoving: true,
      });

      const timers = path.map((point, index) =>
        setTimeout(() => {
          const existing = officeAgentStateRef.current.get(target.id);
          if (!existing) return;

          officeAgentStateRef.current.set(target.id, {
            ...existing,
            ...target,
            x: point.x,
            y: point.y,
            zone: target.zone,
            isMoving: index < path.length - 1,
          });

          publishOfficeAgents();

          if (index === path.length - 1) {
            moveTimersRef.current.delete(target.id);
          }
        }, index === 0 ? 16 : index * OFFICE_MOVE_STEP_MS)
      );

      moveTimersRef.current.set(target.id, timers);
    }

    publishOfficeAgents();
  }, [officeTargets]);

  // Idle wandering — agents randomly shift within their zone
  useEffect(() => {
    const wanderTimers = new Map();

    const startWander = () => {
      const currentMap = officeAgentStateRef.current;

      for (const [agentId, agent] of currentMap.entries()) {
        if (agent.isMoving) continue;

        // Random delay so agents don't all move at once
        const delay = Math.random() * WANDER_INTERVAL_MS;

        const timerId = setTimeout(() => {
          const current = officeAgentStateRef.current.get(agentId);
          if (!current || current.isMoving) return;

          // Find base slot for this agent's zone
          const slots = zoneSlots[current.zone];
          if (!slots || !slots.length) return;

          // Wander within WANDER_RANGE of current position
          const offsetX = (Math.random() - 0.5) * WANDER_RANGE * 2;
          const offsetY = (Math.random() - 0.5) * WANDER_RANGE * 2;
          const newX = current.x + offsetX;
          const newY = current.y + offsetY;

          officeAgentStateRef.current.set(agentId, {
            ...current,
            x: newX,
            y: newY,
          });

          publishOfficeAgents();
        }, delay);

        wanderTimers.set(agentId, timerId);
      }
    };

    const intervalId = setInterval(startWander, WANDER_INTERVAL_MS);
    // First wander after a short delay
    const initialTimer = setTimeout(startWander, 1000);

    return () => {
      clearInterval(intervalId);
      clearTimeout(initialTimer);
      for (const timerId of wanderTimers.values()) {
        clearTimeout(timerId);
      }
      wanderTimers.clear();
    };
  }, []);

  useEffect(() => {
    const timersMap = moveTimersRef.current;

    return () => {
      for (const timers of timersMap.values()) {
        timers.forEach((timerId) => clearTimeout(timerId));
      }
      timersMap.clear();
    };
  }, []);

  return (
    <section id="openclaw-mission" className="openclaw-mission" aria-live="polite">
      <div className="openclaw-shell">
        <div className="openclaw-window-strip" aria-hidden="true">
          <span className="dot red" />
          <span className="dot yellow" />
          <span className="dot green" />
          <p>OPENCLAW://MISSION-CONTROL</p>
        </div>

        <div className="openclaw-header">
          <p className="openclaw-kicker">OpenClaw Fleet Telemetry</p>
          <h2>Mission Control</h2>
          <p className="openclaw-description">
            Assistants move around this pixel office in real time based on status:
            active at desks, standby in the issue zone, and idle in the breakroom.
          </p>

          <div className="openclaw-metrics">
            <article className="openclaw-metric-card">
              <span className="metric-label">Agents</span>
              <strong>{numberFormatter.format(feed.summary?.agentCount || 0)}</strong>
            </article>
            <article className="openclaw-metric-card">
              <span className="metric-label">Active</span>
              <strong>{numberFormatter.format(feed.summary?.activeNow || 0)}</strong>
            </article>
            <article className="openclaw-metric-card">
              <span className="metric-label">Events / 24h</span>
              <strong>{numberFormatter.format(feed.summary?.events24h || 0)}</strong>
            </article>
            <article className="openclaw-metric-card">
              <span className="metric-label">Snapshot</span>
              <strong>{feed.generatedAt ? formatRelativeTime(feed.generatedAt) : "pending"}</strong>
            </article>
          </div>
        </div>

        <section className="openclaw-panel openclaw-office">
          <div className="panel-title-row">
            <h3>Pixel Office Dashboard</h3>
            <span className="panel-subtitle">
              Auto placement by status
              {connectionStatus === "connected" && " · live"}
              {connectionStatus === "polling" && " · polling 10s"}
              {connectionStatus === "connecting" && " · connecting..."}
              {connectionStatus === "fallback" && " · static"}
            </span>
            {connectionStatus === "connected" && (
              <span className="connection-badge connected" aria-label="Live connection">
                ● Live
              </span>
            )}
            {connectionStatus === "polling" && (
              <span className="connection-badge polling" aria-label="Polling mode">
                ● Polling
              </span>
            )}
          </div>

          <div
            className="openclaw-office-stage"
            style={{
              "--office-bg-url": `url(${getOfficeAssetUrl("office_bg_small.webp")})`,
            }}
          >
            <div className="office-scenery-layer" aria-hidden="true">
              <img className="office-prop sofa-shadow" src={getOfficeAssetUrl("sofa-shadow-v1.png")} alt="" />
              <img className="office-prop sofa" src={getOfficeAssetUrl("sofa-idle-v3.png")} alt="" />
              <img
                className="office-prop coffee-shadow"
                src={getOfficeAssetUrl("coffee-machine-shadow-v1.png")}
                alt=""
              />
              <img className="office-prop desk-main" src={getOfficeAssetUrl("desk-v3.webp")} alt="" />
              <span
                className="office-prop sheet plant-left"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("plants-spritesheet.webp")})`,
                  "--frame-x": "0px",
                  "--frame-y": "0px",
                }}
              />
              <span
                className="office-prop sheet plant-right"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("plants-spritesheet.webp")})`,
                  "--frame-x": "-160px",
                  "--frame-y": "-160px",
                }}
              />
              <span
                className="office-prop sheet plant-bottom"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("plants-spritesheet.webp")})`,
                  "--frame-x": "-320px",
                  "--frame-y": "0px",
                }}
              />
              <span
                className="office-prop sheet poster"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("posters-spritesheet.webp")})`,
                  "--frame-x": "0px",
                  "--frame-y": "0px",
                }}
              />
              <span
                className="office-prop sheet server-rack"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("serverroom-spritesheet.webp")})`,
                }}
              />
              <span
                className="office-prop sheet coffee-machine"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("coffee-machine-v3-grid.webp")})`,
                }}
              />
              <span
                className="office-prop sheet cat"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("cats-spritesheet.webp")})`,
                }}
              />
              <span
                className="office-prop sheet flowers-bloom"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("flowers-bloom-v2.webp")})`,
                }}
              />
              <span
                className="office-prop sheet sync-anim"
                style={{
                  "--sheet-url": `url(${getOfficeAssetUrl("sync-animation-v3-grid.webp")})`,
                }}
              />
            </div>

            <div className="office-zone zone-breakroom">
              <h4>{zoneLabel.breakroom}</h4>
              <p>{zoneDescription.breakroom}</p>
            </div>
            <div className="office-zone zone-desk">
              <h4>{zoneLabel.desk}</h4>
              <p>{zoneDescription.desk}</p>
            </div>
            <div className="office-zone zone-issue">
              <h4>{zoneLabel.issue}</h4>
              <p>{zoneDescription.issue}</p>
            </div>

            <div className="office-agent-layer">
              {officeRenderAgents.map((agent) => {
                const spriteInfo = getSpriteInfo(agent.id);
                const displayName = getDisplayName(agent.id, agent.name);
                const agentDepth = 300 + Math.round((agent.y || 0) * 5);
                const hueStyle = spriteInfo.hueRotate ? { filter: `hue-rotate(${spriteInfo.hueRotate}deg)` } : {};

                return (
                  <article
                    key={`office-${agent.id}`}
                    className={`office-agent status-${agent.status}${agent.isMoving ? " moving" : ""}`}
                    style={{ left: `${agent.x}%`, top: `${agent.y}%`, zIndex: agentDepth }}
                    title={`${displayName} · ${statusLabel[agent.status] || agent.status}`}
                  >
                    <div className="office-agent-visual">
                      {spriteInfo.url ? (
                        <span
                          className="office-agent-sprite"
                          style={{ "--sprite-url": `url(${spriteInfo.url})`, ...hueStyle }}
                          aria-hidden="true"
                        />
                      ) : (
                        <span className="agent-portrait-fallback" aria-hidden="true">
                          ?
                        </span>
                      )}
                    </div>
                    {getBubbleText(agent) && <span className="office-agent-bubble">{getBubbleText(agent)}</span>}
                    <span className="office-agent-name">{displayName}</span>
                  </article>
                );
              })}
            </div>
          </div>

          <ul className="office-legend">
            <li>
              <span className="legend-swatch active" />
              <span>Active → Desk Zone</span>
            </li>
            <li>
              <span className="legend-swatch standby" />
              <span>Standby → Problem Solving</span>
            </li>
            <li>
              <span className="legend-swatch idle" />
              <span>Idle → Breakroom</span>
            </li>
          </ul>
        </section>

        <div className="openclaw-grid single-panel">
          <section className="openclaw-panel openclaw-roster">
            <div className="panel-title-row">
              <h3>Agent Roster</h3>
              <span className="panel-subtitle">Status by latest signal and memory write</span>
            </div>

            {loading && <p className="openclaw-state">Loading agent feed...</p>}
            {!loading && error && <p className="openclaw-state">{error}</p>}

            {!loading && !error && agents.length === 0 && (
              <p className="openclaw-state">No agent data found in current snapshot.</p>
            )}

            {!loading && !error && agents.length > 0 && (
              <div className="openclaw-agent-list">
                {agents.map((agent) => {
                  const displayName = getDisplayName(agent.id, agent.name);

                  return (
                    <article key={agent.id} className={`openclaw-agent-card status-${agent.status}`}>
                      <div className="agent-head">
                        <div className="agent-portrait">
                          {getSpriteInfo(agent.id).url ? (
                            <span
                              className="agent-portrait-sprite"
                              style={{
                                "--sprite-url": `url(${getSpriteInfo(agent.id).url})`,
                                ...(getSpriteInfo(agent.id).hueRotate ? { filter: `hue-rotate(${getSpriteInfo(agent.id).hueRotate}deg)` } : {}),
                              }}
                              aria-hidden="true"
                            />
                          ) : (
                            <span className="agent-portrait-fallback" aria-hidden="true">
                              ?
                            </span>
                          )}
                        </div>

                        <div className="agent-identity">
                          <span className="agent-dot" aria-hidden="true" />
                          <div>
                            <h4>{displayName}</h4>
                          </div>
                        </div>

                        <span className={`agent-badge status-${agent.status}`}>
                          {statusLabel[agent.status] || "UNKNOWN"}
                        </span>
                      </div>

                      <dl className="agent-details">
                        <div>
                          <dt>Model</dt>
                          <dd>{agent.model || "-"}</dd>
                        </div>
                        <div>
                          <dt>Workspace</dt>
                          <dd>{agent.workspace || "-"}</dd>
                        </div>
                        <div>
                          <dt>Signal</dt>
                          <dd title={formatAbsoluteTime(agent.lastSignalAt)}>
                            {formatRelativeTime(agent.lastSignalAt)}
                          </dd>
                        </div>
                        <div>
                          <dt>Events</dt>
                          <dd>{numberFormatter.format(agent.events24h || 0)} / 24h</dd>
                        </div>
                      </dl>

                      {agent.recentMemory && (
                        <p className="agent-memory">
                          <span>Latest memory:</span> {agent.recentMemory.title}
                        </p>
                      )}

                      {agent.lastAction && (
                        <p className="agent-last-event">
                          Last event: <strong>{agent.lastAction}</strong> via{" "}
                          {sourceLabel[agent.lastSource] || agent.lastSource || "unknown"}
                        </p>
                      )}
                    </article>
                  );
                })}
              </div>
            )}
          </section>

        </div>
      </div>
    </section>
  );
};

export default OpenClawMissionControl;
